"""Render the published formula-recognition accuracy comparison."""
import html,json
from pathlib import Path
root=Path(__file__).resolve().parent
data=json.loads((root/'recognition-accuracy.json').read_text())
rows=''.join('<tr><td>'+html.escape(r['dataset'])+'</td><td>'+f"{r['samples']:,}"+'</td><td>'+f"{r['ExpRate']:.2f}%"+'</td><td>'+f"{r['CDM_ExpRate']:.2f}%"+'</td></tr>' for r in data['results'])
(root/'accuracy.html').write_text('''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>수식 인식 정확도와 도입 판단</title><style>body{font:16px/1.75 system-ui,sans-serif;max-width:1050px;margin:40px auto;padding:0 20px;color:#19312e;background:#f5f7f2}h1{line-height:1.35}table{border-collapse:collapse;width:100%;background:white}th,td{padding:12px;text-align:left;border-bottom:1px solid #d8e0da}a{color:#176b51}.table-wrap{overflow:auto}section{margin:28px 0}strong{color:#176b51}</style><h1>수식 인식은 얼마나 쓸 만한가?</h1><p>개별 수식의 LaTeX 추출을 먼저 시험하고, 판서 전체 자동 변환은 우선순위를 낮춥니다.</p><section><h2>수식 전체 정답률</h2><p>ExpRate는 식 전체가 맞은 비율입니다. 렌더 비교 기반 전체 정답률은 LaTeX 표기가 달라도 같은 모습으로 표현된 식을 함께 평가합니다.</p><p>Uni-MuMER Qwen3-VL-2B · 저자 공개 결과 · 확인일 2026-11-02</p><div class="table-wrap"><table><thead><tr><th>입력/데이터셋</th><th>식 개수</th><th>ExpRate</th><th>렌더 비교 기반 전체 정답률</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p><a href="'''+html.escape(data['source'],quote=True)+'''">공식 결과 표</a></p><p>BLEU 92점이나 평균 CDM 97점은 수식 100개 중 그만큼을 바로 쓸 수 있다는 뜻과 다릅니다. 기능 도입 판단에는 식 전체 정답률과 교정 시간을 봅니다.</p></section><section><h2>개인 프로젝트에서의 판단</h2><p><strong>짧은 식을 복사해 쓰는 선택 기능부터</strong> 시작하는 편이 좋습니다. 전체 정답률 80%라면 식 20개 중 평균 4개는 확인·수정 대상입니다.</p><p>팩토리얼은 작은 기호와 점의 보존, 연립식은 여러 줄의 묶음, 행렬은 행·열·괄호의 구조가 중요합니다.</p><p>간단한 식·연립식·행렬·기호 중심 식을 각 10개씩 골라 후보 두 개를 비교합니다. 프로젝트 목표는 40개 중 36개 이상을 수정 없이 사용하고, 나머지도 직접 입력보다 빠르게 고치는 것입니다. 짧은 식만 잘 되면 범위를 좁히고, 교정에 시간이 더 들면 LaTeX를 미루고 OCR에 집중합니다.</p></section><p><a href="../../docs/C_SURVEY.md#41-인식-정확도와-실사용-판단">상세 보고서</a> · <a href="examples/index.html">실제 판서 전처리 예시</a></p></html>''')
print('Built accuracy.html')
